#!/usr/bin/env python3
"""Starter: complete the identity boundary implementation described in PROTOCOL.md."""
import json
import sys


def process(batch):
    # Preserve input ordering and per-job output cardinality while implementing
    # parsing, alias resolution, boundary authorization, and wire normalization.
    return {"results": [{"status": "reject", "reason": "unauthenticated"}
                        for _ in batch["jobs"]]}


if __name__ == "__main__":
    json.dump(process(json.load(sys.stdin)), sys.stdout)
